<script setup> import { ref, onMounted, computed } from'vue' import { useRoute, useRouter } from'vue-router' import { useFormulairesStore } from'../stores/formulaires' import { useModalStore } from'../stores/modal' import DashboardLayout from'../components/layouts/DashboardLayout.vue' import { VueDraggableNext as draggable } from'vue-draggable-next' import { ArrowLeft, Plus, Settings, Trash2, GripVertical, Check, X, Type, Mail, Phone, Calendar, Hash, List, CheckSquare, AlignLeft, FileUp, Save, } from'lucide-vue-next' const route = useRoute() const router = useRouter() const store = useFormulairesStore() const modalStore = useModalStore() const formulaireId = route.params.id const activeField = ref(null) const saving = ref(false) const fieldTypes = [ { value:'TEXTE', label:'Texte court', icon: Type }, { value:'ZONE_TEXTE', label:'Paragraphe', icon: AlignLeft }, { value:'EMAIL', label:'Email', icon: Mail }, { value:'TELEPHONE', label:'Téléphone', icon: Phone }, { value:'DATE', label:'Date', icon: Calendar }, { value:'NOMBRE', label:'Nombre', icon: Hash }, { value:'LISTE_DEROULANTE', label:'Liste déroulante', icon: List }, { value:'CHOIX_MULTIPLES', label:'Choix multiples', icon: CheckSquare }, { value:'CASE_A_COCHER', label:'Cases à cocher', icon: CheckSquare }, { value:'FICHIER', label:'Fichier / CV', icon: FileUp }, onMounted(async () => { await store.fetchFormulaireById(formulaireId) }) const form = computed(() => store.currentFormulaire) // --- Actions Champs --- const addField = async (type) => { const newField = { libelle: `Nouveau champ ${fieldTypes.find((t) => t.value === type).label}`, type: type, obligatoire: true, description:'', options: ['LISTE_DEROULANTE','CHOIX_MULTIPLES','CASE_A_COCHER'].includes(type) ? [ { libelle:'Option 1', ordre: 0 }, { libelle:'Option 2', ordre: 1 }, : [], } const created = await store.addChamp(formulaireId, newField) if (created) { activeField.value = created } } const deleteField = async (champId) => { const confirmed = await modalStore.showConfirm( 'Êtes-vous sûr de vouloir supprimer ce champ ?', 'Supprimer la question', { confirmText:'Supprimer', variant:'danger' } ) if (confirmed) { await store.deleteChamp(champId) if (activeField.value?.id === champId) activeField.value = null } } const saveActiveField = async () => { if (!activeField.value) return saving.value = true await store.updateChamp(activeField.value.id, activeField.value) saving.value = false activeField.value = null // Désélectionne après sauvegarde } // --- Options (pour listes/choix) --- const addOption = () => { if (activeField.value) { const ordre = activeField.value.options?.length || 0 activeField.value.options.push({ libelle: `Option ${ordre + 1}`, ordre }) } } const removeOption = (index) => { if (activeField.value) { activeField.value.options.splice(index, 1) } } // --- Drag & Drop --- const onDragEnd = async (evt) => { if (!form.value) return // Les champs dans l'UI ont été réordonnés par le v-model de draggable // On récupère les IDs dans le nouvel ordre const orderedIds = form.value.champs.map((c) => c.id) await store.reorderChamps(formulaireId, orderedIds) } </script> <template> <DashboardLayout> <template #header> <div class="flex items-center w-full"> <button @click="router.push('/formulaires')" class="mr-4 p-2 rounded-full hover:bg-white transition-colors" > <ArrowLeft class="w-5 h-5 text-[#01313E]/80"/> </button> <div class="flex-1"> <h2 class="text-xl font-semibold text-[#01313E]">{{ form?.titre ||'Chargement...' }}</h2> <p class="text-sm text-[#01313E]/60">Constructeur de formulaire</p> </div> </div> </template> <div class="flex h-[calc(100vh-8rem)] gap-6"v-if="form"> <!-- Zone de construction principale --> <div class="flex-1 flex flex-col min-w-0 bg-white rounded-2xl border border-[#01313E]/10 overflow-hidden" > <!-- Toolbar Ajout de champs --> <div class="p-4 border-b border-[#01313E]/10 bg-white flex items-center gap-2 overflow-x-auto no-scrollbar" > <span class="text-xs font-semibold text-[#01313E]/60 uppercase tracking-wider mr-2" >Ajouter :</span > <button v-for="ft in fieldTypes" :key="ft.value" @click="addField(ft.value)" class="inline-flex items-center px-3 py-1.5 rounded-lg bg-white border border-[#01313E]/10 text-sm font-medium text-[#01313E]/80 hover:border-[#E30046] hover:text-[#E30046]-600 transition-colors whitespace-nowrap" > <component :is="ft.icon"class="w-4 h-4 mr-1.5"/> {{ ft.label }} </button> </div> <!-- Canvas (Liste des champs) --> <div class="flex-1 overflow-y-auto p-6 bg-white/50"> <div v-if="form.champs.length === 0" class="h-full flex flex-col items-center justify-center text-[#01313E]/60" > <List class="w-12 h-12 mb-3 text-white"/> <p>Ce formulaire est vide. Ajoutez des champs via la barre d'outils.</p> </div> <draggable v-model="form.champs" handle=".drag-handle" @end="onDragEnd" class="space-y-4 max-w-3xl mx-auto pb-20" item-key="id" > <template #item="{ element }"> <div class="bg-white rounded-xl border p-5 relative transition-all group cursor-pointer" :class="activeField?.id === element.id ?'border-[#E30046] ring-1' :'border-[#01313E]/10 hover:border-[#E30046]'" @click="activeField = element" > <!-- Drag Handle --> <div class="absolute top-0 left-0 bottom-0 w-8 flex items-center justify-center cursor-grab opacity-0 group-hover:opacity-100 transition-opacity drag-handle" > <GripVertical class="w-5 h-5 text-[#01313E]/60"/> </div> <div class="ml-6"> <div class="flex justify-between items-start mb-2"> <h4 class="font-medium text-[#01313E] flex items-center"> {{ element.libelle }} <span v-if="element.obligatoire"class="text-[#E30046] ml-1">*</span> </h4> <span class="text-xs bg-white text-[#01313E]/80 px-2 py-1 rounded-md">{{ fieldTypes.find((t) => t.value === element.type)?.label }}</span> </div> <p v-if="element.description"class="text-xs text-[#01313E]/60 mb-3"> {{ element.description }} </p> <!-- Fake Input preview --> <div class="opacity-70 pointer-events-none mt-2"> <input v-if=" ['TEXTE','EMAIL','TELEPHONE','DATE','NOMBRE'].includes(element.type)" type="text" class="input-field py-1.5 bg-white" :placeholder="element.placeholderTexte ||'...'" /> <textarea v-if="element.type ==='ZONE_TEXTE'" rows="2" class="input-field py-1.5 bg-white" ></textarea> <div v-if="element.type ==='LISTE_DEROULANTE'" class="input-field py-1.5 bg-white flex items-center justify-between" > <span class="text-[#01313E]/60">Sélectionner...</span> </div> <div v-if=" element.options?.length && ['CHOIX_MULTIPLES','CASE_A_COCHER'].includes(element.type)" class="space-y-2 mt-2" > <div v-for="opt in element.options" :key="opt.id" class="flex items-center text-sm text-[#01313E]/80" > <div class="w-4 h-4 border border-[#01313E]/10 rounded-sm mr-2"></div> {{ opt.libelle }} </div> </div> </div> </div> <!-- Delete Button --> <button @click.stop="deleteField(element.id)" class="absolute top-4 right-4 p-1.5 text-[#01313E]/60 hover:text-[#E30046] hover:bg-white rounded-lg opacity-0 group-hover:opacity-100 transition-all" > <Trash2 class="w-4 h-4"/> </button> </div> </template> </draggable> </div> </div> <!-- Panneau latéral : Propriétés du champ actif --> <div class="w-80 flex-shrink-0 bg-white rounded-2xl border border-[#01313E]/10 flex flex-col overflow-hidden" > <div class="p-4 border-b border-[#01313E]/10 bg-white flex items-center justify-between"> <h3 class="font-medium text-[#01313E] flex items-center"> <Settings class="w-4 h-4 mr-2 text-[#01313E]/60"/> Paramètres du champ </h3> <button v-if="activeField" @click="activeField = null" class="text-[#01313E]/60 hover:text-[#01313E]/80" > <X class="w-4 h-4"/> </button> </div> <div class="p-4 flex-1 overflow-y-auto"v-if="activeField"> <div class="space-y-4"> <div> <label class="block text-sm font-medium text-[#01313E]/80">Libellé</label> <input type="text"v-model="activeField.libelle"class="input-field mt-1"/> </div> <div> <label class="block text-sm font-medium text-[#01313E]/80" >Texte d'aide (Description)</label > <textarea v-model="activeField.description" rows="2" class="input-field mt-1 text-sm" ></textarea> </div> <div v-if="['TEXTE','EMAIL','TELEPHONE','NOMBRE'].includes(activeField.type)"> <label class="block text-sm font-medium text-[#01313E]/80">Placeholder</label> <input type="text"v-model="activeField.placeholderTexte"class="input-field mt-1"/> </div> <div class="flex items-center mt-4"> <input type="checkbox" v-model="activeField.obligatoire" id="obl" class="h-4 w-4 text-[#E30046]-600 focus:border-[#01313E]/10 rounded" /> <label for="obl"class="ml-2 block text-sm text-[#01313E]">Champ obligatoire</label> </div> <!-- Paramètres pour fichiers --> <template v-if="activeField.type ==='FICHIER'"> <hr class="border-[#01313E]/10 my-4"/> <div> <label class="block text-sm font-medium text-[#01313E]/80">Extensions autorisées</label> <input type="text" v-model="activeField.typesMimeAutorises" class="input-field mt-1" placeholder=".pdf,.docx" /> </div> <div class="mt-2"> <label class="block text-sm font-medium text-[#01313E]/80">Taille max (Mo)</label> <input type="number"v-model="activeField.tailleMaxMo"class="input-field mt-1"/> </div> </template> <!-- Gestion des Options --> <template v-if=" ['LISTE_DEROULANTE','CHOIX_MULTIPLES','CASE_A_COCHER'].includes(activeField.type)" > <hr class="border-[#01313E]/10 my-4"/> <div class="flex items-center justify-between mb-2"> <label class="block text-sm font-medium text-[#01313E]/80">Options</label> <button @click="addOption" class="text-xs text-[#E30046]-600 hover:text-[#01313E] font-medium flex items-center" > <Plus class="w-3 h-3 mr-1"/> Ajouter </button> </div> <div class="space-y-2"> <div v-for="(opt, idx) in activeField.options" :key="idx" class="flex items-center gap-2" > <input type="text" v-model="opt.libelle" class="input-field py-1 text-sm flex-1" /> <button @click="removeOption(idx)"class="text-[#01313E]/60 hover:text-[#E30046] p-1"> <X class="w-4 h-4"/> </button> </div> <p v-if="!activeField.options?.length"class="text-xs text-[#E30046]"> Au moins une option est requise. </p> </div> </template> </div> </div> <div v-else class="p-6 text-center text-[#01313E]/60"> <p class="text-sm">Cliquez sur un champ pour modifier ses paramètres.</p> </div> <div class="p-4 border-t border-[#01313E]/10 bg-white"v-if="activeField"> <button @click="saveActiveField":disabled="saving"class="btn-primary w-full"> <Loader2 v-if="saving"class="w-4 h-4 mr-2 animate-spin"/> <Save v-else class="w-4 h-4 mr-2"/> Sauvegarder le champ </button> </div> </div> </div> </DashboardLayout> </template> 